void setMotor(int pwm_pin, int dir1, int dir2, int speed) {
    if (speed > 0) {
        digitalWrite(dir1, HIGH);
        digitalWrite(dir2, LOW);
    } else {
        digitalWrite(dir1, LOW);
        digitalWrite(dir2, HIGH);
    }
    analogWrite(pwm_pin, abs(speed));
}

